input.command:
cd /Users/bymyway/.openclaw && python3 -c "
import json
d = json.load(open('openclaw.json'))
def find_key(obj, key, path=''):
    results=[]
    if isinstance(obj, dict):
        for k,v in obj.items():
            newpath = f'{path}.{k}' if path else k
            if key.lower() in k.lower():
                results.append((newpath, v if not isinstance(v,(dict,list)) else '...'))
            results += find_key(v, key, newpath)
    elif isinstance(obj, list):
        for i,v in enumerate(obj):
            results += find_key(v, key, f'{path}[{i}]')
    return results
for k in ['memorySearch','memsearch','vector','plugin']:
    print('===', k, '===')
    for p,v in find_key(d, k):
        print(p, '=', v)
"

cat openclaw.json 2>/dev/null | python3 -c "
import json,sys
d=json.load(sys.stdin)
print('version-related keys:')
for k in d:
    if 'version' in k.lower():
        print(k, d[k])
" ; echo "---npm version check---"; find . -maxdepth 1 -name "package.json" -exec cat {} \; 2>/dev/null | python3 -c "import json,sys; d=json.load(sys.stdin); print(d.get('version'))" 2>/dev/null; openclaw --version 2>/dev/null; echo "---heartbeat config---"; python3 -c "
import json
d=json.load(open('openclaw.json'))
def find_key(obj,key,path=''):
    r=[]
    if isinstance(obj,dict):
        for k,v in obj.items():
            p=f'{path}.{k}' if path else k
            if key.lower() in k.lower(): r.append((p, v if not isinstance(v,(dict,list)) else '...'))
            r+=find_key(v,key,p)
    elif isinstance(obj,list):
        for i,v in enumerate(obj): r+=find_key(v,key,f'{path}[{i}]')
    return r
for p,v in find_key(d,'heartbeat'): print(p,'=',v)
"

